CREATE TYPE "auth_token_purpose" AS ENUM ('email_verification', 'password_reset');
CREATE TABLE "auth_sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "token_hash" text NOT NULL, "expires_at" timestamptz NOT NULL, "last_used_at" timestamptz DEFAULT now() NOT NULL, "revoked_at" timestamptz, "user_agent" text, "ip_address" text, "created_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "auth_sessions_token_hash_unique" UNIQUE("token_hash"));
CREATE INDEX "auth_sessions_user_idx" ON "auth_sessions" ("user_id", "created_at");
CREATE TABLE "auth_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "purpose" "auth_token_purpose" NOT NULL, "token_hash" text NOT NULL, "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "auth_tokens_token_hash_unique" UNIQUE("token_hash"));
CREATE INDEX "auth_tokens_user_purpose_idx" ON "auth_tokens" ("user_id", "purpose", "created_at");
CREATE TABLE "auth_rate_limits" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "key" text NOT NULL, "attempts" text DEFAULT '0' NOT NULL, "window_started_at" timestamptz DEFAULT now() NOT NULL, "blocked_until" timestamptz, "updated_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "auth_rate_limits_key_unique" UNIQUE("key"));
